/**
 * Цветовые схемы вишлиста.
 *
 * `value` совпадает с именем CSS-класса в globals.css и со значением
 * colorScheme в шаблонах на бэке (config templates.json) — расхождение здесь
 * означало бы, что созданный по шаблону вишлист открывается без темы.
 *
 * `colors` — фон и акцент для образцов в селекторе.
 */
export const colorSchema = [
  { name: 'Космос',   value: 'space',     kind: 'dark',  colors: [ '#0B1226', '#8BE9F5' ] },
  { name: 'Полночь',  value: 'midnight',  kind: 'dark',  colors: [ '#0B1433', '#FFD166' ] },
  { name: 'Графит',   value: 'graphite',  kind: 'dark',  colors: [ '#121316', '#F2A541' ] },
  { name: 'Лаванда',  value: 'lavender',  kind: 'dark',  colors: [ '#0C0C1E', '#B9AEFF' ] },
  { name: 'Малахит',  value: 'malachite', kind: 'dark',  colors: [ '#0E1A15', '#D8B46A' ] },
  { name: 'Лагуна',   value: 'lagoon',    kind: 'dark',  colors: [ '#07161A', '#5EEAD4' ] },
  { name: 'Пудра',    value: 'powder',    kind: 'light', colors: [ '#FBF3F5', '#C93A6E' ] },
  { name: 'Лён',      value: 'linen',     kind: 'light', colors: [ '#F6F4EF', '#85693A' ] },
  { name: 'Пастель',  value: 'pastel',    kind: 'light', colors: [ '#F5F6FA', '#C23A6C' ] },
] as const

export type ColorSchemeValue = (typeof colorSchema)[number]['value'] | typeof CUSTOM_SCHEME

/** Значение colorScheme, при котором цвета берутся из settings.customScheme. */
export const CUSTOM_SCHEME = 'custom'

/**
 * Старые схемы → новые.
 *
 * Обратная совместимость не приоритет, но терять тему у существующих
 * вишлистов незачем: сопоставляем по светлоте и семейству акцента. Там, где
 * точного соответствия нет (светло-зелёная «мята»), берём ближайшую светлую.
 */
const LEGACY_SCHEMES: Record<string, string> = {
  aurora: 'space',
  cosmic: 'lavender',
  crimson: 'lavender',
  forest: 'malachite',
  ember: 'graphite',
  cloud: 'pastel',
  mint: 'linen',
  sand: 'linen',
  blush: 'powder',
  // старая «lavender» была светлой — одноимённая новая тёмная, поэтому
  // сопоставляем со светлой «Пастелью», а не с самой собой
}

const KNOWN_SCHEMES = new Set<string>(colorSchema.map(s => s.value))

/** Имя CSS-класса схемы: новое значение как есть, старое — через таблицу. */
export function normalizeScheme(scheme: string | undefined | null): string {
  if (!scheme) return 'space'
  if (scheme === CUSTOM_SCHEME) return CUSTOM_SCHEME
  if (KNOWN_SCHEMES.has(scheme)) return scheme
  // Старая «lavender» светлая, новая тёмная: отдельной строкой в таблице её
  // не задать, потому что ключ совпадает с известным значением.
  return LEGACY_SCHEMES[scheme] ?? 'space'
}

/** Акценты «своей схемы»: пара «для тёмной базы» / «для светлой». */
